    52  static int fuzz_card_connect(const uint8_t *data, size_t size, sc_pkcs11_slot_t **slot_out)
    53  {
    54          /* Works in the same manner as card_detect() for only one slot and card with virtual reader */
    55          struct sc_pkcs11_card *p11card = NULL;
    56          struct sc_reader *reader = NULL;
    57          struct sc_app_info *app_generic = NULL;
    58          sc_pkcs11_slot_t *slot = NULL;
    59          int rv = CKR_OK, free_p11card = 0;
    60
    61          /* Erase possible virtual slots*/
    62          list_clear(&virtual_slots);
    63
    64          /* Erase possible readers from context */
    65          while (list_size(&context->readers)) {
    66                  sc_reader_t *rdr = (sc_reader_t *) list_get_at(&context->readers, 0);
    67                  _sc_delete_reader(context, rdr);
    68          }
    69          if (context->reader_driver->ops->finish != NULL)
    70                  context->reader_driver->ops->finish(context);
    71
    72          /* Create virtual reader */
    73          context->reader_driver = sc_get_fuzz_driver();
    74          fuzz_add_reader(context, data, size);
    75          reader = sc_ctx_get_reader(context, 0);
    76
    77          /* Add slot for reader */
    78          if (create_slot(reader) != CKR_OK) {
    79                  goto fail;
    80          }
    81
    82          /* Locate a slot related to the reader */
    83          for (size_t i = 0; i < list_size(&virtual_slots); i++) {
    84                  slot = (sc_pkcs11_slot_t *) list_get_at(&virtual_slots, i);
    85                  if (slot->reader == reader) {
    86                          p11card = slot->p11card;
    87                          break;
    88                  }
    89          }
    90
    91          /* Create p11card */
    92          p11card = (struct sc_pkcs11_card *)calloc(1, sizeof(struct sc_pkcs11_card));
    93          p11card->reader = reader;
    94          free_p11card = 1;
    95
    96          /* Connect card to reader */
    97          if ((rv = sc_connect_card(reader, &p11card->card)) != SC_SUCCESS) {
    98                  goto fail;
    99          }
   100          init_slot_info(&slot->slot_info, reader);
   101
   102          /* Instead of detecting framework*/
   103          p11card->framework = &framework_pkcs15;
   104
   105          /* Bind 'generic' application or (emulated?) card without applications */
   106          app_generic = sc_pkcs15_get_application_by_type(p11card->card, "generic");
   107          if (app_generic || !p11card->card->app_count) {
   108                  scconf_block *conf_block = NULL;
   109
   110                  conf_block = sc_match_atr_block(p11card->card->ctx, NULL, &p11card->reader->atr);
   111                  if (!conf_block) /* check default block */
   112                          conf_block = sc_get_conf_block(context, "framework", "pkcs15", 1);
   113
   114                  rv = p11card->framework->bind(p11card, app_generic);
   115                  if (rv != CKR_TOKEN_NOT_RECOGNIZED && rv != CKR_OK)
   116                          goto fail;
   117
   118                  rv = p11card->framework->create_tokens(p11card, app_generic);
   119                  if (rv != CKR_OK)
   120                          goto fail;
   121                  free_p11card = 0;
   122          }
   123
   124          /* Bind rest of application*/
   125          for (int j = 0; j < p11card->card->app_count; j++)   {
   126                  struct sc_app_info *app_info = p11card->card->app[j];
   127
   128                  if (app_generic && app_generic == p11card->card->app[j])
   129                          continue;
   130
   131                  if (p11card->framework->bind(p11card, app_info) != CKR_OK) {
   132                          continue;
   133                  }
   134                  rv = p11card->framework->create_tokens(p11card, app_info);
   135                  if (rv != CKR_OK) {
   136                          goto fail;
   137                  }
   138                  free_p11card = 0;
   139          }
   140          if (slot_out)
   141                  *slot_out = slot;
   142  fail:
   143          if (free_p11card) {
   144                  sc_pkcs11_card_free(p11card);
   145          }
   146          return rv;
   147  }
