    35  void fuzz_get_chunk(sc_reader_t *reader, const uint8_t **chunk, uint16_t *chunk_size)
    36  {
    37      struct driver_data *data;
    38      uint16_t c_size;
    39      const uint8_t *c;
    40
    41      if (chunk)
    42          *chunk = NULL;
    43      if (chunk_size)
    44          *chunk_size = 0;
    45
    46      if (!chunk || !chunk_size || !reader) {
    47          if (reader)
    48              sc_debug(reader->ctx, SC_LOG_DEBUG_VERBOSE_TOOL, "Invalid Arguments");
    49          return;
    50      }
    51      data = reader->drv_data;
    52      if (!data || !data->Data || data->Size < sizeof c_size) {
    53          sc_debug(reader->ctx, SC_LOG_DEBUG_VERBOSE_TOOL, "Invalid Arguments");
    54          return;
    55      }
    56      /* parse the length of the returned data on two bytes */
    57      c_size = *((uint16_t *) data->Data);
    58      /* consume two bytes from the fuzzing data */
    59      data->Size -= sizeof c_size;
    60      data->Data += sizeof c_size;
    61
    62      if (data->Size < c_size) {
    63          c_size = data->Size;
    64      }
    65
    66      /* consume the bytes from the fuzzing data */
    67      c = data->Data;
    68      data->Size -= c_size;
    69      data->Data += c_size;
    70
    71      sc_debug_hex(reader->ctx, SC_LOG_DEBUG_VERBOSE_TOOL,
    72          "Returning fuzzing chunk", c, c_size);
    73
    74      *chunk = c;
    75      *chunk_size = c_size;
    76  }
